// R463, R261: Devreux's Influences, each tapped in full from her Motivation of that name.
const infl = (oid: Oid, name: string, points: number, n: number): Influence => {
  const src = `${DEVREUX}:${name}`;
  return { kind: 'influence', oid, home: DEVREUX, where: 'drawer', n, name, sign: 1, points, used: false, crit: false,
    tap: { ledger: { [src]: points / 2 }, current: src }, mot: true };
};

export function scene(sam = 'Player 1', beauford = 'Player 2'): PieceRecord[] {
  // R360: the GM put the Stagger on Beauford, a player's character: a contribution, public.
  const chip: Chip = { kind: 'chip', oid: '00000007', where: { slot: BEAUFORD, name: 'stagger' }, n: 0, sign: -1, points: 2, rider: false, by: 'GM' };
  const sticky: Sticky = { kind: 'sticky', oid: '00000008', place: at(1430, 20), text: STICKY, big: true };
  const ref: Reference = { kind: 'reference', oid: '00000009', place: at(1430, 650), which: 'actions' };
  return [
    character(SAM, sam, 'Sam', 40, SAM_FRONT, back({ min: 2 }, 'Fire tools. Lantern. 6 Candles.\nPocket knife. Bedroll. Canteen.\nRope. Notebook and pencil.')),
    character(BEAUFORD, beauford, 'Beauford', 500, BEAUFORD_FRONT, back({ min: 1 })),
    character(DEVREUX, 'GM', 'Devreux', 960, DEVREUX_FRONT, back({ min: 2 })),
    infl('00000004', 'Keep the Peace', 4, 0),
    infl('00000005', 'Self-Preservation', 4, 1),
    infl('00000006', 'Old Sympathy for Sparkers', 2, 2),
    chip, sticky, ref,
    // R418: the Connection Table, put away, holding the adventure's *Connections in Unton*.
    seed('0000000a', at(1430, 900), DEVREUX),
  ];
}

export const PLAYTEST = 'The 11-08 playtest';

/** The records a new game starts with besides its pieces: no burials, round 0, an empty book and tape. */
export function singletons(): [Rid, Rec][] {
  return [['yards', empty()], ['meta', { round: 0, rolls: 0 }], ['book', { claims: {}, gv: 0, tomb: {} }], ['tape', { receipts: [] }]];
}

/** The whole playtest game, rid → record. */
export function playtest(sam?: string, beauford?: string): [Rid, Rec][] {
  return [...scene(sam, beauford).map((r): [Rid, Rec] => [ridOf(r.oid), r]), ...singletons()];
}
