// CRC: crc-PoolView.md, crc-Drag.md | Seq: seq-drag.md#1.7 | R225, R39, R40, R41, R42, R43, R366, R367, R46, R47, R48, R50, R55, R56, R57, R59, R60, R64, R463, R268, R269, R360, R366, R369, R486
// What a click or a drop on a pool, a drawer or a glyph does to the game, as one change. Pure: each
// takes the game and gives a writer for Game.change (or null when nothing happens), so the views stay
// thin and these are tested without a browser.

import type { Game, Writer } from '../model/game.ts';
import {
  PLAYER_OIDS, oidOf, onTable, ridOf, type Character, type Chip, type Influence, type Oid, type Place, type Rec,
  type Rid, type Sign, type SlotName, type Where, type Who,
} from '../model/records.ts';
import { lowerCard, lowerChip, raiseCard, raiseChip, MIN } from '../rules/influence.ts';
import { accepts, type Item } from '../rules/pool.ts';
import { allowFlag, feed, kill, tap, undoFlag, unfeed, type Holder, type Lookup, type Tapped } from '../rules/tap.ts';

export type Change = (w: Writer) => void;

// Players mint at random in their range so two players can't collide; the GM counts up below it.
/** A source of new oids for one change. */
export function minter(game: Game, gm: boolean, rng: () => number = Math.random): () => Oid {
  const used = new Set(game.all().map(([rid]) => rid).filter(onTable).map(oidOf));   // a torn roll's oid is taken too
  let top = 0;
  for (const o of used) { const n = parseInt(o, 16); if (n < PLAYER_OIDS) top = Math.max(top, n); }
  return () => {
    let oid: Oid;
    do {
      oid = (gm ? ++top : PLAYER_OIDS + Math.floor(rng() * (0xffffffff - PLAYER_OIDS))).toString(16).padStart(8, '0');
    } while (used.has(oid));
    used.add(oid);
    return oid;
  };
}

const lookup = (game: Game): Lookup => oid => game.get(ridOf(oid)) as Holder | undefined;
const item = (game: Game, rid: Rid): Item | undefined => {
  const r = game.get(rid) as Rec | undefined;
  return r && 'kind' in r && (r.kind === 'chip' || r.kind === 'influence') ? r : undefined;
};
const inSlot = (i: Item, owner: Oid, slot: SlotName) =>
  typeof i.where === 'object' && 'slot' in i.where && i.where.slot === owner && i.where.name === slot;

/** The chips and cards in one slot. */
export function slotItems(game: Game, owner: Oid, slot: SlotName): Item[] {
  return game.all().map(([rid]) => item(game, rid)).filter((i): i is Item => !!i && inSlot(i, owner, slot));
}

// R39, R47: a chip or card dropped on a slot joins it (a Damage card only its own kind's slot).
// R360: a chip coming into the pool takes the name of whoever put it there (`by`); one moved between
// the pool's own slots keeps its own.
export function toSlot(game: Game, rid: Rid, owner: Oid, slot: SlotName, _mint: () => Oid, by?: Who): Change | null {
  const i = item(game, rid);
  if (!i || !accepts(slot, i)) return null;
  // R463: a Motivation's card dropped in a Main slot joins that character's drawer.
  const home = i.kind === 'influence' && i.mot ? { home: owner } : {};
  const inPool = typeof i.where === 'object' && 'slot' in i.where && i.where.slot === owner;
  const moved = { ...i, ...home, where: { slot: owner, name: slot }, n: slotItems(game, owner, slot).length } as Item;
  // A chip coming into the pool takes the putter's name; moved within it, it keeps its own.
  if (moved.kind === 'chip' && !inPool) { if (by) moved.by = by; else delete moved.by; }
  // R366: chips never merge; a Roll Up is worked out where it is drawn and counted.
  return w => w.put(ridOf(moved.oid), moved);
}

/** A drawer's cards in order. */
export function drawerCards(game: Game, owner: Oid): Influence[] {
  return game.all().map(([, r]) => r)
    .filter((r): r is Influence => 'kind' in r && r.kind === 'influence' && r.home === owner && r.where === 'drawer')
    .sort((a, b) => a.n - b.n);
}

// R48, R239, R240: a card goes home to a drawer, at `at` among its other cards or last; another
// character's drawer makes it theirs. The drawer is renumbered in order.
export function toDrawer(game: Game, rid: Rid, owner: Oid, at?: number): Change | null {
  const i = item(game, rid);
  if (!i || i.kind !== 'influence') return null;
  const order = drawerCards(game, owner).filter(k => ridOf(k.oid) !== rid);
  const card: Influence = { ...i, home: owner, where: 'drawer', used: false };
  order.splice(at === undefined ? order.length : Math.max(0, Math.min(at, order.length)), 0, card);
  return w => order.forEach((k, n) => { if (k === card || k.n !== n) w.put(ridOf(k.oid), { ...k, n }); });
}

// R48, R60: dropped anywhere else, a plain card goes home; a tap may wait loose; a chip lies there.
export function toTable(game: Game, rid: Rid, at: Place): Change | null {
  const i = item(game, rid);
  if (!i) return null;
  if (i.kind === 'influence' && !i.tap) return toDrawer(game, rid, i.home);
  return w => w.put(rid, { ...i, where: { table: at } });
}

// R268, R59: the kill box deletes a card; an unused tap gives its Levels back.
export function killCard(game: Game, rid: Rid): Change | null {
  const i = item(game, rid);
  if (!i || i.kind !== 'influence') return null;
  const refunds = kill(lookup(game), i);
  return w => { w.del(rid); for (const c of refunds) w.put(ridOf(c.oid), c); };
}

/** Plain chips just vanish (put away on the bar). */
export function vanish(game: Game, rid: Rid): Change | null {
  const i = item(game, rid);
  return i?.kind === 'chip' ? w => w.del(rid) : null;
}

// R40, R42, R46: click raises, shift lowers; lowering can complete a Roll Up, worked out where it is
// drawn. R369: a chip raises or lowers itself, in a pile or not.
export function chipClick(game: Game, rid: Rid, shift: boolean, _mint?: () => Oid): Change | null {
  const c = item(game, rid);
  if (c?.kind !== 'chip') return null;
  const next = shift ? lowerChip(c) : raiseChip(c);
  return w => { if (next) w.put(rid, next); else w.del(rid); };
}

// R43: clicking a rider does nothing; shift-clicking removes it.
export function riderClick(game: Game, rid: Rid, shift: boolean): Change | null {
  const c = item(game, rid);
  if (c?.kind !== 'chip' || !c.rider || !shift) return null;
  return w => w.put(rid, { ...c, rider: false });
}

// R41: a click on a slot's empty space adds a loose +1; shift-click a −1. R360: by whoever clicked.
export function addLoose(game: Game, owner: Oid, slot: SlotName, shift: boolean, mint: () => Oid, by?: Who): Change {
  const chip: Chip = { kind: 'chip', oid: mint(), where: { slot: owner, name: slot }, n: slotItems(game, owner, slot).length,
    sign: shift ? -1 : 1, points: 1, rider: false, ...(by && { by }) };
  return w => w.put(ridOf(chip.oid), chip);
}

// R269, R56: a card's Level: click raises, shift lowers; a resource-made card feeds and unfeeds.
// R268: shift-click at Min deletes it, as the kill box does.
export function cardClick(game: Game, rid: Rid, shift: boolean, mint: () => Oid): Change | null {
  const c = item(game, rid);
  if (c?.kind !== 'influence') return null;
  if (shift && c.points <= MIN) return killCard(game, rid);
  if (c.tap) {
    const t = shift ? unfeed(lookup(game), c) : feed(lookup(game), c, undefined, mint());
    return t ? apply(t, c) : null;
  }
  const next = shift ? lowerCard(c) : raiseCard(c);
  return next.points === c.points ? null : w => w.put(rid, next);
}

// R464: the GM rules on a flagged tap: Allow keeps it, unflagged; Undo gives back what was fed under it.
export function ruleFlag(game: Game, rid: Rid, allow: boolean): Change | null {
  const c = item(game, rid);
  if (c?.kind !== 'influence' || !c.flag) return null;
  if (allow) { const next = allowFlag(c); return w => w.put(rid, next); }
  const t = undoFlag(lookup(game), c);
  return t ? apply(t, c) : null;
}

// R50: a drawer's writers make a new card at Min.
// R50, R239: written last in its drawer.
export function writeCard(game: Game, owner: Oid, sign: Sign, name: string, mint: () => Oid): Change {
  const n = drawerCards(game, owner).reduce((m, k) => Math.max(m, k.n + 1), 0);
  const card: Influence = { kind: 'influence', oid: mint(), home: owner, where: 'drawer', n, name, sign, points: MIN, used: false, crit: false };
  return w => w.put(ridOf(card.oid), card);
}

// R64: a card in the used pile, clicked, goes back to the drawer for the next roll.
export function restoreUsed(game: Game, rid: Rid): Change | null {
  const c = item(game, rid);
  return c?.kind === 'influence' && c.where === 'used' ? w => w.put(rid, { ...c, where: 'drawer', used: false }) : null;
}

function apply(t: Tapped, old?: Influence): Change {
  return w => {
    if (old && t.card.oid !== old.oid) w.put(ridOf(old.oid), old);
    w.put(ridOf(t.card.oid), t.card);
    for (const c of t.changed) w.put(ridOf(c.oid), c);
  };
}

// R55, R57: a glyph dragged out makes a card at Min where it lands; dropped on a resource-made card,
// it feeds that card a Level and becomes its current source.
export function tapOut(game: Game, src: string, where: Where, mint: () => Oid): Change | null {
  const t = tap(lookup(game), src, where, mint());
  return t ? apply(t) : null;
}

export function feedFrom(game: Game, cardRid: Rid, src: string, mint: () => Oid): Change | null {
  const c = item(game, cardRid);
  if (c?.kind !== 'influence') return null;
  const t = feed(lookup(game), c, src, mint());
  return t ? apply(t, c) : null;
}

// R225, R57: a resource-made card carried onto another of its kind merges into it: each Level goes
// back to the source it came from and is fed into that card instead, and the carried card is gone.
export function mergeTap(game: Game, fromRid: Rid, intoRid: Rid, mint: () => Oid): Change | null {
  const from = item(game, fromRid), into = item(game, intoRid);
  if (fromRid === intoRid || from?.kind !== 'influence' || into?.kind !== 'influence' || !from.tap || !into.tap || from.used) return null;
  const chars = new Map<Oid, Holder>();
  const now: Lookup = oid => chars.get(oid) ?? lookup(game)(oid);
  for (const c of kill(now, from)) chars.set(c.oid, c);
  let card = into, fed = false;
  for (const [src, n] of Object.entries(from.tap.ledger)) {
    for (let k = 0; k < n; k++) {
      const t = feed(now, card, src, mint());
      if (!t || t.card.oid !== into.oid) return null;   // a source of another kind, or a used card
      card = t.card;
      fed = true;
      for (const c of t.changed) chars.set(c.oid, c);
    }
  }
  if (!fed) return null;
  return w => {
    w.del(fromRid);
    w.put(intoRid, card);
    for (const c of chars.values()) w.put(ridOf(c.oid), c);
  };
}
