// CRC: crc-BootHillView.md | R118, R120, R121, R122, R123, R124, R125, R289, R295, R404, R405, R428, R488, R489
// Boot Hill at the bar's right end: the gravestone with its badge, and the graveyard list under it.
// The rules are Yards' (pure); this draws them, digs up at the press, and arms deleting forever.

import type { Game } from '../model/game.ts';
import { ridFor, ridOf, type Burial, type Character, type Connections, type Hill, type Oid, type Opinion, type PieceRecord, type Yards } from '../model/records.ts';
import { empty, exhume, exhumeOwn, forget, forgetAll, forgetOwn, forgetOwnIn, lastCard, next, ownIn, prev, raised, rename, withInfo, type At } from '../rules/yards.ts';
import { rowOf, synced, tableOf } from '../rules/connections.ts';
import { Doom } from './doom.ts';
import { gesture, type PointerLike } from './gesture.ts';


export type BootHillWith = {
  game: Game;
  /** The graveyard browsed and whether the list is open, kept in the Seat (R127). */
  cur: () => number; setCur: (cur: number) => void;
  open: () => boolean; setOpen: (open: boolean) => void;
  toWorld: (clientX: number, clientY: number) => { x: number; y: number };
  /** The height a dug-up piece lands at: on top of everything. */
  top: () => number;
  /** Carries a dug-up piece from the press (a character by its pool). */
  carry: (lead: PieceRecord, down: PointerLike, move: PointerLike) => void;
  /** R404, R405, R428: slides an Info card (by its place) or a record (`o<oid>`) out of its NPC's card (the Seat). */
  slideInfo: (oid: Oid, k: number | string) => void;
};

export class BootHillView {
  #w: BootHillWith;
  #stone: HTMLButtonElement;
  #badge: HTMLElement;
  #panel: HTMLElement;
  #name: HTMLInputElement;
  #prev: HTMLButtonElement;
  #items: HTMLElement;
  #dooms = new Doom();

  constructor(bar: HTMLElement, root: HTMLElement, w: BootHillWith) {
    this.#w = w;
    const doc = bar.ownerDocument;
    this.#stone = doc.createElement('button');
    this.#stone.id = 'boothill';
    this.#stone.title = "Boot Hill: everything put away. Click to see what's buried here.";
    const stone = doc.createElement('span');
    stone.className = 'stone';
    stone.append('Boot', doc.createElement('br'), 'Hill');
    this.#badge = doc.createElement('span');
    this.#badge.className = 'n';
    this.#stone.append(stone, this.#badge);
    bar.append(this.#stone);

    // R121: the header (‹, the name, ›) stays put while the list scrolls.
    this.#panel = doc.createElement('div');
    this.#panel.id = 'graves';
    const nav = doc.createElement('div');
    nav.className = 'yard';
    this.#prev = doc.createElement('button');
    this.#prev.textContent = '‹';
    this.#prev.setAttribute('aria-label', 'The graveyard before');
    const nextB = doc.createElement('button');
    nextB.textContent = '›';
    nextB.setAttribute('aria-label', 'The next graveyard, or a new one');
    this.#name = doc.createElement('input');
    this.#name.className = 'yname';
    this.#name.spellcheck = false;
    this.#name.placeholder = 'Unnamed graveyard';
    this.#name.setAttribute('aria-label', 'Graveyard name');
    this.#name.title = 'Rename this graveyard. Shift-click twice to delete everything in it.';
    nav.append(this.#prev, this.#name, nextB);
    this.#items = doc.createElement('div');
    this.#items.className = 'items';
    this.#panel.append(nav, this.#items);
    root.append(this.#panel);

    const browse = (f: (y: Yards, cur: number) => { yards: Yards; cur: number }, hill?: Hill) => {
      const b = f(this.#yards(), this.#cur());
      this.#w.game.change(x => { x.put('yards', b.yards); if (hill) x.put('hill', hill); });
      this.#w.setCur(b.cur);
      this.render();
    };
    gesture(this.#stone, { click: () => { this.#w.setOpen(!this.#w.open()); this.render(); } });
    gesture(this.#prev, { click: () => browse(prev) });
    gesture(nextB, { click: () => browse(next) });
    // R124: typing names the graveyard; leaving the name erased lets an empty one go.
    this.#name.addEventListener('input', () => {
      const y = this.#yards(), cur = this.#cur(), n = this.#name.value;
      this.#w.game.change(x => x.put('yards', { yards: y.yards.map((g, i) => i === cur ? { ...g, name: n, named: n.trim() !== '' } : g) }));
    });
    this.#name.addEventListener('change', () => browse((y, cur) => rename(y, cur, this.#name.value)));
    // R125: two shift-clicks on the name delete everything in this graveyard.
    gesture(this.#name, { shift: e => {
      (e as Event).preventDefault?.();
      // R489: this page's own buried tapes here go too.
      if (this.#yards().yards[this.#cur()]?.items.length || this.#own().length) this.#dooms.arm(this.#name, 'Delete everything here? Shift-click again',
        () => browse(forgetAll, forgetOwnIn(this.#hill(), this.#yards(), this.#cur())));
    } });
    // R289: a press anywhere else closes the list.
    doc.addEventListener('pointerdown', e => {
      if (!this.#w.open() || (e.target as HTMLElement).closest?.('#graves, #boothill')) return;
      this.#w.setOpen(false);
      this.render();
    }, true);
    w.game.listen(rids => { if (rids.has('yards') || rids.has('hill')) this.render(); });
    this.render();
  }

  #yards(): Yards { return (this.#w.game.get('yards') as Yards | undefined) ?? empty(); }
  #cur(): number { return Math.min(this.#w.cur(), this.#yards().yards.length - 1); }
  /** R488: this page's own burials, never sent. */
  #hill(): Hill { return (this.#w.game.get('hill') as Hill | undefined) ?? { hill: [] }; }
  /** R489: the Hill's indices of those the graveyard browsed shows. */
  #own(): number[] { return ownIn(this.#hill(), this.#yards(), this.#cur()); }

  // R289: the badge counts every graveyard; the stone fades when nothing is buried.
  render(): void {
    const y = this.#yards(), cur = this.#cur(), g = y.yards[cur]!, doc = this.#panel.ownerDocument;
    const total = y.yards.reduce((n, x) => n + x.items.length, 0) + this.#hill().hill.length;   // R488
    this.#badge.textContent = total ? String(total) : '';
    this.#stone.classList.toggle('empty', !total);
    this.#panel.hidden = !this.#w.open();
    this.#prev.disabled = cur === 0;
    if (doc.activeElement !== this.#name && this.#dooms.armed !== this.#name) this.#name.value = g.name;
    if (this.#dooms.armed && this.#dooms.armed !== this.#name) this.#dooms.drop();
    // R289: oldest first; an empty graveyard says so.
    const own = this.#own(), hill = this.#hill();
    if (!g.items.length && !own.length) {
      const p = doc.createElement('p');
      p.textContent = 'Nothing is buried here.';
      this.#items.replaceChildren(p);
      return;
    }
    this.#items.replaceChildren(...g.items.map((burial, item) => {
      const b = doc.createElement('button');
      b.textContent = burial.name;
      b.title = 'Drag this back onto the table. Shift-click or long-press twice to delete it forever.';
      // R406: a GM card a player sees is the GM's to bring back.
      if (burial.gm && !burial.info) b.title = 'A card the GM put away';
      // R120, R295: dragged a few pixels it comes up under the pointer and the list closes; a
      // shift-click or a long press arms deleting it forever (R125).
      gesture(b, {
        drag: (_down, move) => this.#digUp(item, move),
        shift: () => this.#dooms.arm(b, 'Delete forever? Shift-click again', () => {
          const f = forget(this.#yards(), this.#cur(), { yard: this.#cur(), item });
          this.#w.game.change(x => x.put('yards', f.yards));
          this.#w.setCur(f.cur);
          this.render();
        }),
      });
      return b;
    }), ...own.map(k => {
      // R488: this page's own buried tape, after the graveyard's shared burials.
      const b = doc.createElement('button');
      b.textContent = hill.hill[k]!.burial.name;
      b.title = 'Your own: drag this back onto the table. Shift-click or long-press twice to delete it forever.';
      gesture(b, {
        drag: (_down, move) => this.#digUpOwn(k, move),
        shift: () => this.#dooms.arm(b, 'Delete forever? Shift-click again', () => {
          this.#w.game.change(x => x.put('hill', forgetOwn(this.#hill(), k)));
          this.render();
        }),
      });
      return b;
    }));
  }

  /** R404, R428: digs up the newest Info card or record buried in this graveyard whose NPC is here; false when none. */
  undoCard(): boolean {
    const cur = this.#cur(), at = lastCard(this.#yards(), cur, b => (b.info ? !!this.#npc(b.info.oid) : !!this.#holderCard(b)));
    return !!at && this.#cardUp(at);
  }

  /** A buried record's, and a card of its NPC or group on the table. */
  #holderCard(b: Burial): { record: Opinion; table: Connections; card: Character } | undefined {
    const record = b.records[0];
    if (record?.kind !== 'opinion') return undefined;
    const all = this.#w.game.all().map(([, r]) => r as PieceRecord);
    const table = tableOf(all);
    const card = table && all.find((c): c is Character => c.kind === 'character' && rowOf(table, c)?.id === record.holder);
    return table && card ? { record, table, card } : undefined;
  }

  #cardUp(at: At): boolean {
    const b = this.#yards().yards[at.yard]?.items[at.item];
    return b?.info ? this.#infoUp(at) : this.#recordUp(at);
  }

  // R428: a record comes back, its Connection written to its cell again, slid out under a card of its
  // NPC or group; while none is on the table it stays buried.
  #recordUp(at: At): boolean {
    const b = this.#yards().yards[at.yard]?.items[at.item], up = b && this.#holderCard(b);
    if (!up) return false;
    const dug = exhume(this.#yards(), this.#cur(), at);
    this.#w.game.change(x => { x.put('yards', dug.yards); x.put(ridOf(up.record.oid), up.record); x.put(ridOf(up.table.oid), synced(up.table, up.record)); });
    this.#w.setCur(dug.cur);
    this.#w.slideInfo(up.card.oid, `o${up.record.oid}`);
    return true;
  }

  #npc(oid: Oid): Character | undefined {
    const c = this.#w.game.get(ridOf(oid)) as Character | undefined;
    return c?.kind === 'character' ? c : undefined;
  }

  // R405: an Info card comes up on its NPC, slid out; while its NPC is gone it stays buried.
  #infoUp(at: At): boolean {
    const dug = exhume(this.#yards(), this.#cur(), at), c = dug.info && this.#npc(dug.info.oid);
    if (!dug.info || !c) return false;
    const back = withInfo(c, dug.info);
    this.#w.game.change(x => { x.put('yards', dug.yards); x.put(ridOf(c.oid), back.character); });
    this.#w.setCur(dug.cur);
    this.#w.slideInfo(c.oid, back.k);
    return true;
  }

  #digUp(item: number, e: PointerLike): void {
    const cur = this.#cur();
    if (this.#yards().yards[cur]?.items[item]?.gm) {
      if (this.#cardUp({ yard: cur, item })) { this.#w.setOpen(false); this.render(); }
      return;
    }
    const dug = exhume(this.#yards(), cur, { yard: cur, item });
    const recs = raised(dug.records, this.#w.toWorld(e.clientX, e.clientY), this.#w.top());
    if (!recs.length) return;
    this.#w.game.change(x => {
      x.put('yards', dug.yards);
      for (const r of recs) x.put(ridFor(r), r);
    });
    this.#w.setCur(dug.cur);
    this.#w.setOpen(false);
    this.render();
    // It came up under the pointer, so it is carried from here, not from the press in the list.
    this.#w.carry(recs[0]!, e, e);
  }

  // R488: this page's own buried tape comes up as its torn roll, this page's alone.
  #digUpOwn(k: number, e: PointerLike): void {
    const dug = exhumeOwn(this.#hill(), k);
    const recs = raised(dug.records, this.#w.toWorld(e.clientX, e.clientY), this.#w.top());
    if (!recs.length) return;
    this.#w.game.change(x => {
      x.put('hill', dug.hill);
      for (const r of recs) x.put(ridFor(r), r);
    });
    this.#w.setOpen(false);
    this.render();
    this.#w.carry(recs[0]!, e, e);
  }

}

type KeyLike = { key: string; ctrlKey: boolean; metaKey: boolean; shiftKey: boolean; altKey: boolean; target: EventTarget | null };

/** R404: Ctrl+Z or ⌘Z with the focus in no text being written, which keeps its own undo. */
export function isPageUndo(ev: KeyLike): boolean {
  if (ev.key.toLowerCase() !== 'z' || !(ev.ctrlKey || ev.metaKey) || ev.shiftKey || ev.altKey) return false;
  const t = ev.target as HTMLElement | null;
  return !(t?.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t?.tagName ?? ''));
}
